// A history request mutates nothing and queues behind no turn: the store answers it as asked.
async function answerListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  try {
    const summaries = await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before});
    sendSessionList(ws, (summaries ?? []).map(sessionSummaryFrame));
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    log.error('ws', 'listing sessions failed', {sessionId: session.sessionId, userId: session.userId, error: reason});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list sessions');
  }
}

// The wire carries ISO strings: a Date does not survive JSON.stringify as a Date.
function sessionSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: new Date(summary.createdAt).toISOString(),
    updatedAt: new Date(summary.updatedAt).toISOString(),
    entryCount: summary.entryCount,
  };
}
